#!/usr/bin/env bash
# Generated by: Claude Opus 5.5
# Generation date: 2026-10-11
#
# Start an Ollama server from a GHCR image as a Singularity instance.
#
# Usage: run-server.sh <model> [version|latest] [port]
#   model    base | ministral-3-3b | gemma4-e4b
#   version  X.Y.Z, X.Y.Z-alpha.N, X.Y.Z-beta.N, or "latest" (default: newest release)
#   port     default 11434; use another port to run a second model side by side
#
# Env:
#   LLM_SIF_DIR      required; where ollama-<model>_<version>.sif files live
#   LLM_MODELS_DIR   required for "base"; bound at /models
#   LLM_DATA_DIR     default ~/llm-data; server logs go to $LLM_DATA_DIR/logs
#   OLLAMA_ENV_FILE  optional env file for Ollama overrides (passed with --env-file)
#   SINGULARITY      default "singularity"
set -euo pipefail

# shellcheck source=scripts/common.sh
source "$(dirname "$(readlink -f "$0")")/common.sh"

[[ $# -ge 1 && $# -le 3 ]] || die "usage: $(basename "$0") <model> [version|latest] [port]"
model=$1
port=${3:-11434}

require "$SINGULARITY" curl jq setsid nohup
check_model "$model"
if ! [[ "$port" =~ ^[0-9]+$ ]] || (( port < 1024 || port > 65535 )); then
  die "port must be 1024-65535"
fi
: "${LLM_SIF_DIR:?LLM_SIF_DIR must be set (directory for SIF files)}"
if [[ "$model" == base ]]; then
  : "${LLM_MODELS_DIR:?LLM_MODELS_DIR must be set for base (model store bound at /models)}"
  [[ -d "$LLM_MODELS_DIR" ]] || die "LLM_MODELS_DIR '$LLM_MODELS_DIR' is not a directory"
fi

version=$(resolve_version "$model" "${2:-latest}")
sif=$(sif_path "$model" "$version")
instance="ollama-$model"
log_dir="${LLM_DATA_DIR:-$HOME/llm-data}/logs"

running=$(instance_image "$instance")
if [[ -n "$running" ]]; then
  if [[ "$running" == "$sif" ]]; then
    if server_up "$port"; then
      echo "$instance $version is already running on 127.0.0.1:$port"
      exit 0
    fi
    die "$instance $version is running but not answering on port $port (started on another port?); see $log_dir/$instance.log or stop it: stop-server.sh $model"
  fi
  die "$instance is already running from $running; stop it first: stop-server.sh $model"
fi
server_up "$port" && die "port $port is already in use"

if [[ ! -f "$sif" ]]; then
  mkdir -p "$LLM_SIF_DIR"
  echo "Pulling ghcr.io/$IMAGE_REPO/ollama-$model:$version -> $sif"
  "$SINGULARITY" pull "$sif" "docker://ghcr.io/$IMAGE_REPO/ollama-$model:$version"
fi

binds=()
if [[ "$model" == base ]]; then binds=(--bind "$LLM_MODELS_DIR:/models"); fi
"$SINGULARITY" instance start --containall --cleanenv "${binds[@]}" "$sif" "$instance"

env_args=(--cleanenv --env "OLLAMA_HOST=127.0.0.1:$port")
if [[ -n "${OLLAMA_ENV_FILE:-}" ]]; then env_args+=(--env-file "$OLLAMA_ENV_FILE"); fi

# The env goes on the exec: a process exec'd into an instance does not inherit
# the instance's start-up env. setsid + nohup detach the server from this
# terminal, so it survives the script exiting and the terminal closing.
mkdir -p "$log_dir"
chmod 700 "$log_dir"
log="$log_dir/$instance.log"
setsid nohup "$SINGULARITY" exec "${env_args[@]}" "instance://$instance" ollama serve \
  >"$log" 2>&1 </dev/null &

for _ in $(seq 60); do
  if server_up "$port"; then
    echo "$instance $version listening on 127.0.0.1:$port (log: $log)"
    echo "Stop with: $(dirname "$0")/stop-server.sh $model"
    exit 0
  fi
  sleep 1
done

tail -n 20 "$log" >&2 || true
"$SINGULARITY" instance stop "$instance" >/dev/null 2>&1 || true
die "server did not answer on port $port within 60 s; instance stopped"
